<?php
require_once __DIR__ . '/includes/functions.php';
require_once __DIR__ . '/includes/lesson_book_store.php';
require_login();
$scope=in_array((string)($_GET['scope']??''),['class','teacher'],true)?(string)$_GET['scope']:'class';
$target=trim((string)($_GET[$scope]??''));
if($target===''){http_response_code(422);exit($scope==='class'?'Chưa chọn lớp cần xuất.':'Chưa chọn giáo viên cần xuất.');}
$paper=in_array((string)($_GET['paper']??''),['a4_pair','a3'],true)?(string)$_GET['paper']:'a4_pair';
$session=(string)($_GET['session']??'all');$onlyFilled=!empty($_GET['only_filled']);$includeCover=!empty($_GET['include_cover']);
$weeks=lb_weeks();$from=(string)($_GET['from_week']??'');$to=(string)($_GET['to_week']??$from);$selected=[];$active=false;
foreach($weeks as$w){if((string)$w['key']===$from)$active=true;if($active)$selected[]=$w;if((string)$w['key']===$to&&$active)break;}
if(!$selected&&($w=lb_week($from)))$selected=[$w];if(!$selected){http_response_code(422);exit('Không tìm thấy tuần học cần xuất.');}
$bundles=[];$allRows=[];
foreach($selected as$w){$rows=array_values(array_filter(lb_slots($w),function($r)use($scope,$target,$session,$onlyFilled){if(!lb_can_view($r))return false;if($scope==='class'&&!lb_same($target,(string)($r['class']??'')))return false;if($scope==='teacher'&&!lb_same($target,(string)($r['scheduled_teacher']??''))&&!lb_same($target,(string)($r['actual_teacher']??'')))return false;$s=lb_norm((string)($r['session']??''));if($session==='morning'&&strpos($s,'sang')===false)return false;if($session==='afternoon'&&strpos($s,'chieu')===false)return false;if($onlyFilled&&trim((string)($r['lesson_title']??''))===''&&trim((string)($r['teacher_comment']??''))===''&&(string)($r['status']??'pending')==='pending')return false;return true;}));
 foreach(['Sáng','Chiều']as$part){$partRows=array_values(array_filter($rows,fn($r)=>lb_same($part,(string)($r['session']??''))));if($partRows)$bundles[]=['week'=>$w,'session'=>$part,'rows'=>$partRows];}$allRows=array_merge($allRows,$rows);
}
$validation=lb_print_validation($allRows);$settings=lb_settings();$ps=$settings['print'];
function lbp_sig(array $r): string {$p=(string)($r['signature_path']??'');if($p===''||!is_file($p))return'';$raw=@file_get_contents($p);return$raw===false?'':'data:image/png;base64,'.base64_encode($raw);}
function lbp_day(array $r): string {$n=(int)date('N',strtotime((string)$r['date']))+1;return'Thứ '.$n.'<br>'.date('d/m/Y',strtotime((string)$r['date']));}
function lbp_scores(array $r): array {$rating=(string)($r['rating']??'');$sum=['Tốt'=>10,'Khá'=>8,'Trung bình'=>6,'Yếu'=>4][$rating]??'';return[$sum,$rating];}
function lbp_group_counts(array $rows): array {$c=[];foreach($rows as$r){$k=(string)$r['date'];$c[$k]=($c[$k]??0)+1;}return$c;}
$title=$scope==='class'?'LỚP '.$target:'GIÁO VIÊN '.$target;
