<?php $pageNo=0;if($includeCover):$pageNo++;?><section class="page cover <?=!empty($ps['mirrored_margins'])?'mirror':''?>"><div>TRƯỜNG <?=e(defined('SCHOOL_NAME')?SCHOOL_NAME:'')?></div><h1>SỔ GHI ĐẦU BÀI</h1><h2><?=e($title)?></h2><p>Từ <?=date('d/m/Y',strtotime($selected[0]['start']))?> đến <?=date('d/m/Y',strtotime($selected[count($selected)-1]['end']))?></p><p>Năm học <?=e(date('Y',strtotime($selected[0]['start'])).' – '.date('Y',strtotime($selected[count($selected)-1]['end'])))?></p></section><?php endif;?>
<?php foreach($bundles as$b):$counts=lbp_group_counts($b['rows']);$seen=[];$w=$b['week'];if($paper==='a3'):$pageNo++;?><section class="page a3 <?=($pageNo%2?'odd':'even')?> <?=!empty($ps['mirrored_margins'])?'mirror':''?>"><div class="head"><div>SỔ GHI ĐẦU BÀI · <?=e($title)?></div><div class="week"><?=e($w['label'])?> · BUỔI <?=mb_strtoupper($b['session'],'UTF-8')?> (<?=date('d/m/Y',strtotime($w['start']))?>–<?=date('d/m/Y',strtotime($w['end']))?>)</div></div><table><thead><tr><th>Thứ ngày/tháng</th><th>Tiết</th><?php if($scope==='teacher'):?><th>Lớp</th><?php endif;?><th>Môn học</th><th>Tiết PPCT</th><th>Tên HS nghỉ tiết</th><th>Đầu bài / nội dung</th><th>Nhận xét GV</th><th>Cộng</th><th>XL</th><th>Ký tên</th></tr></thead><tbody><?php foreach($b['rows']as$r):[$sum,$rating]=lbp_scores($r);?><tr><?php if(empty($seen[$r['date']])):$seen[$r['date']]=true;?><td rowspan="<?=$counts[$r['date']]?>"><?=lbp_day($r)?></td><?php endif;?><td><?=e($r['period'])?></td><?php if($scope==='teacher'):?><td><?=e($r['class'])?></td><?php endif;?><td><?=e($r['subject'])?></td><td><?=e($r['ppct_period']??'')?></td><td><?=e($r['absent_names']??'')?></td><td class="text-left"><?=e($r['lesson_title']??'')?></td><td class="text-left"><?=e($r['teacher_comment']??'')?></td><td><?=e($sum)?></td><td><?=e($rating)?></td><td><?php if($src=lbp_sig($r)):?><img class="sig" src="<?=$src?>"><?php endif;?></td></tr><?php endforeach;?></tbody></table><div class="signatures"><div>GIÁO VIÊN CHỦ NHIỆM<br><br><br><?=e($ps['homeroom_name'])?></div><div>BAN GIÁM HIỆU<br><br><br><?=e($ps['leader_name'])?></div></div></section>
<?php else:$pageNo++;$seen=[];?><section class="page odd <?=!empty($ps['mirrored_margins'])?'mirror':''?>"><div class="head"><div>SỔ GHI ĐẦU BÀI · <?=e($title)?></div><div class="week"><?=e($w['label'])?> · BUỔI <?=mb_strtoupper($b['session'],'UTF-8')?></div></div><div class="spread-note">Trang trái – Nội dung tiết học</div><table class="left"><thead><tr><th class="c-day">Thứ ngày/tháng</th><th class="c-period">Tiết</th><th class="c-subject"><?=$scope==='teacher'?'Lớp / Môn':'Môn học'?></th><th class="c-ppct">Tiết PPCT</th><th class="c-absent">Tên HS nghỉ tiết</th><th class="c-title">Đầu bài hay nội dung công việc</th></tr></thead><tbody><?php foreach($b['rows']as$r):?><tr><?php if(empty($seen[$r['date']])):$seen[$r['date']]=true;?><td rowspan="<?=$counts[$r['date']]?>"><?=lbp_day($r)?></td><?php endif;?><td><?=e($r['period'])?></td><td><?=e(($scope==='teacher'?$r['class'].' / ':'').$r['subject'])?></td><td><?=e($r['ppct_period']??'')?></td><td><?=e($r['absent_names']??'')?></td><td class="text-left"><?=e($r['lesson_title']??'')?></td></tr><?php endforeach;?></tbody></table><div class="footer-box">Tổng số tiết đã dạy: <?=$validation['filled']?> · Số tiết chưa hoàn thành: <?=$validation['pending']?></div></section>
<?php $pageNo++;?><section class="page even <?=!empty($ps['mirrored_margins'])?'mirror':''?>"><div class="head"><div>SỔ GHI ĐẦU BÀI · <?=e($title)?></div><div class="week"><?=e($w['label'])?> · BUỔI <?=mb_strtoupper($b['session'],'UTF-8')?></div></div><div class="spread-note">Trang phải – Nhận xét, xếp loại và chữ ký</div><table class="right"><thead><tr><th class="c-comment">Nhận xét của giáo viên</th><th class="score">HT<br>4</th><th class="score">KL<br>3</th><th class="score">VS<br>2</th><th class="score">CC<br>1</th><th class="score">Cộng<br>10</th><th class="c-rating">XL</th><th class="c-sign">Ký tên</th></tr></thead><tbody><?php foreach($b['rows']as$r):[$sum,$rating]=lbp_scores($r);?><tr><td class="text-left"><?=e($r['teacher_comment']??'')?></td><td></td><td></td><td></td><td></td><td><?=e($sum)?></td><td><?=e($rating)?></td><td><?php if($src=lbp_sig($r)):?><img class="sig" src="<?=$src?>"><?php elseif(!empty($r['signed_at'])):?><small>Đã ký</small><?php endif;?></td></tr><?php endforeach;?></tbody></table><div class="footer-box"><b>Nhận xét của giáo viên chủ nhiệm / Ban giám hiệu:</b></div><div class="signatures"><div>GIÁO VIÊN CHỦ NHIỆM<br><br><br><?=e($ps['homeroom_name'])?></div><div>BAN GIÁM HIỆU<br><br><br><?=e($ps['leader_name'])?></div></div></section><?php endif;endforeach;?>
